-
-__attribute__ ((long_call, section (".ramfunc")))
-void banzai() {
-	// Disable all interrupts
-	__disable_irq();
-
-	// Set bootflag to run SAM-BA bootloader at restart
-	const int EEFC_FCMD_CGPB = 0x0C;
-	const int EEFC_KEY = 0x5A;
-	while ((EFC0->EEFC_FSR & EEFC_FSR_FRDY) == 0);
-	EFC0->EEFC_FCR =
-		EEFC_FCR_FCMD(EEFC_FCMD_CGPB) |
-		EEFC_FCR_FARG(1) |
-		EEFC_FCR_FKEY(EEFC_KEY);
-	while ((EFC0->EEFC_FSR & EEFC_FSR_FRDY) == 0);
-
-	// From here flash memory is no more available.
-
-	// BANZAIIIIIII!!!
-	const int RSTC_KEY = 0xA5;
-	RSTC->RSTC_CR =
-		RSTC_CR_KEY(RSTC_KEY) |
-		RSTC_CR_PROCRST |
-		RSTC_CR_PERRST;
-
-	while (true);
-}
-
-static int ticks = -1;
-
-void initiateReset(int _ticks) {
-	ticks = _ticks;
-}
-
-void cancelReset() {
-	ticks = -1;
-}
-
-void tickReset() {
-	if (ticks == -1)
-		return;
-	ticks--;
-	if (ticks == 0)
-		banzai();
-}
-
-#ifdef __cplusplus
-}
-#endif

