-/* Configure PIO interrupt sources */
-static void __initialize() {
-	int i;
-	for (i=0; i<32; i++) {
-		callbacksPioA[i] = NULL;
-		callbacksPioB[i] = NULL;
-		callbacksPioC[i] = NULL;
