- */
-static inline void emac_set_address(Emac* p_emac, uint8_t uc_index,
-		uint8_t* p_mac_addr)
-{
-	p_emac->EMAC_SA[uc_index].EMAC_SAxB = (p_mac_addr[3] << 24)
-			| (p_mac_addr[2] << 16)
-			| (p_mac_addr[1] << 8)
-			| (p_mac_addr[0]);
-	p_emac->EMAC_SA[uc_index].EMAC_SAxT = (p_mac_addr[5] << 8)
-			| (p_mac_addr[4]);
-}
