-    if ( pwYear )
-    {
-        *pwYear = (((dwDate  >> 4) & 0x7) * 1000)
-                 + ((dwDate & 0xF) * 100)
-                 + (((dwDate >> 12) & 0xF) * 10)
-                 + ((dwDate >> 8) & 0xF);
-    }
-
-    /* Retrieve month */
-    if ( pucMonth )
-    {
-        *pucMonth = (((dwDate >> 20) & 1) * 10) + ((dwDate >> 16) & 0xF);
-    }
-
-    /* Retrieve day */
-    if ( pucDay )
-    {
-        *pucDay = (((dwDate >> 28) & 0x3) * 10) + ((dwDate >> 24) & 0xF);
-    }
-
-    /* Retrieve week */
-    if ( pucWeek )
-    {
-        *pucWeek = ((dwDate >> 21) & 0x7);
-    }
